public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1;
    }
    if (N == 1) {
        return 2;
    }
    // The formula for the maximum number of regions created by N triangles in a plane
    // is given by R(N) = 2 + 7N - 3N*(N-1)/2
    // This formula comes from the fact that each new triangle can intersect with all previous triangles
    // in 6 new intersection points, creating additional regions.
    return 2 + 7 * N - (3 * N * (N - 1)) / 2;
}

