public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words cannot be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }
    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    int sumLengths = word1.length() + word2.length();
    int gcd = gcd(common, sumLengths);

    String result = "appx(" + word1 + ", " + word2 + ") = " + (common / gcd) + "/" + (sumLengths / gcd);
    if (common == 0) {
        result = "appx(" + word1 + ", " + word2 + ") = 0";
    } else if (sumLengths == common) {
        result = "appx(" + word1 + ", " + word2 + ") = 1";
    }
    return result;
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] dateParts = date.split(" ");
        if (dateParts.length != 3) {
            throw new IllegalArgumentException("Date must be in the format 'MM dd yyyy'");
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        String[] months = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }

        String monthName = months[month - 1];

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);

        String[] weekdays = {
            "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"
        };
        String weekday = weekdays[calendar.get(java.util.Calendar.DAY_OF_WEEK) - 1];

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Date components must be valid integers", e);
    } catch (IllegalArgumentException e) {
        throw e;
    } catch (Exception e) {
        throw new RuntimeException("An error occurred while processing the date", e);
    }
}

public int[] twoSum(int[] nums, int target) {
