}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    int removeCount = n / 20; // 5% of the elements

    // Sort the array to remove the smallest and largest 5%
    java.util.Arrays.sort(arr);

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    int remainingCount = n - 2 * removeCount;
    return sum / remainingCount;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    if (remainderCount[0] % 2 != 0) {
        return false; // Unpaired elements with remainder 0
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false; // Unpaired elements with remainders i and k-i
        }
    }

    return true;
}

