public int minInsertions(String s) {
    int open = 0; // To track unmatched '('
    int insertions = 0; // To track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++; // Increment open for '('
        } else {
            // For ')'
            if (open == 0) {
                // No matching '(', need to insert one '('
                insertions++;
            } else {
                // Matching '(', decrement open
                open--;
            }
            // Check for consecutive '))'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                // Need one more ')' to make it a pair
                insertions++;
            }
        }
    }

    // Add insertions for any unmatched '('
    insertions += open * 2;

    return insertions;
}

