public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;

    int i;
    for (i = 0; i < heights.length; i++) {
        while (top != -1 && heights[i] <= heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : (i - stack[top] - 1);
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top--]];
        int width = (top == -1) ? i : (i - stack[top] - 1);
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;
    int row = 0, col = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) { // going up
            row = d < cols ? 0 : d - cols + 1;
            col = d < cols ? d : cols - 1;
            while (row < rows && col >= 0) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        } else { // going down
            col = d < rows ? 0 : d - rows + 1;
            row = d < rows ? d : rows - 1;
            while (col < cols && row >= 0) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first decreasing element from the end
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such element is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest element on the right side of (i-th digit) that is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap found elements digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i-th digit)
    j = digits.length - 1;
    while (i + 1 < j) {
        temp = digits[i + 1];
        digits[i + 1] = digits[j];
        digits[j] = temp;
        i++;
        j--;
    }

    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow
    }
}

